import * as D from './domain.js';
import { download, exportCSV, exportXLSX, exportPDF, manualPDF } from './exports.js';

const $=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>new Intl.NumberFormat('pt-BR').format(x||0);
const date=x=>D.validDate(x)?new Date(x+'T12:00:00').toLocaleDateString('pt-BR'):'Não informada';
const dateTime=x=>{const d=new Date(x);return Number.isNaN(d.getTime())?'Data não informada':d.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'});};
const ICONS={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',box:'<path d="m3 7 9-4 9 4v10l-9 4-9-4Z"/><path d="m3 7 9 4 9-4M12 11v10M7 5l10 4"/>',clipboard:'<path d="M9 5H5v16h14V5h-4"/><rect x="9" y="3" width="6" height="4" rx="1"/><path d="m8 13 3 3 5-6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',file:'<path d="M14 3H5v18h14V8Z"/><path d="M14 3v5h5M8 12h8M8 16h5"/>',chart:'<path d="M4 3v18h17M8 16v-5M13 16V6M18 16v-8"/>',book:'<path d="M12 5C9 3 5 3 2 5v15c3-2 7-2 10 0 3-2 7-2 10 0V5c-3-2-7-2-10 0ZM12 5v15"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',qr:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/><rect x="7" y="7" width="3" height="3"/><rect x="14" y="7" width="3" height="3"/><rect x="7" y="14" width="3" height="3"/><path d="M14 14h3v3h-3v-1"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',moon:'<path d="M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',alert:'<path d="M12 3 2 21h20Z"/><path d="M12 9v5m0 3v.5"/>',move:'<path d="M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',edit:'<path d="m4 16-1 5 5-1L20 8l-4-4Z"/><path d="m14 6 4 4"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',volume:'<path d="m11 4-6 5H2v6h3l6 5ZM16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',wifi:'<path d="M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0m-9 4a5 5 0 0 1 6 0M12 20v.1"/>',upload:'<path d="M12 17V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',leaf:'<path d="M20 3C8 1 1 8 5 16s16 5 15-13Z"/><path d="M4 21 15 10"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.file}</svg>`;
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>{el.outerHTML=icon(el.dataset.icon);});}
const NAV=[['inicio','Visão geral','grid'],['registros','Registros','clipboard'],['inventario','Inventário','box'],['conferencia','Conferência','check'],['historico','Histórico','clock'],['relatorios','Relatórios','file'],['dashboard','Dashboard','chart'],['tutorial','Tutorial','book']];
let demo=false;try{demo=sessionStorage.getItem('maripora-demo')==='1';}catch{}
let key=demo?D.DEMO_KEY:D.KEY, state,storageError='',importCandidate=null;
try{state=D.load(localStorage,key);}catch(e){state=D.emptyState();storageError='Não foi possível abrir os dados locais. '+e.message+' A gravação está bloqueada para proteger o conteúdo anterior. Exporte uma cópia em Conta e dados.';}
const ui={inventory:{search:'',type:'',status:'',condition:'',page:1},conference:{search:'',status:'',page:1},history:{search:'',user:'',action:'',from:'',to:'',page:1},reports:{from:'',to:'',type:'',location:'',charts:['condition','species','class','movement']},dashboard:{period:'month',year:new Date().getFullYear()},prefill:'',dirty:false};
let toastTimer,scannerStream,scannerFrame,installPrompt,modalReturnFocus;
const route=()=>{const bits=location.hash.slice(1).split('/');let id='';try{id=bits[1]?decodeURIComponent(bits.slice(1).join('/')):'';}catch{}return {name:bits[0]||'inicio',id};};
const isAdmin=()=>state.profile.role==='admin';
const itemById=id=>state.items.find(i=>i.id===id||i.code===id);
const itemHref=i=>`#ficha/${encodeURIComponent(i.id)}`;
const navHref=(name,id)=>`#${name}${id?'/'+encodeURIComponent(id):''}`;
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200);}
function commit(fn,message){
  if(storageError)throw new Error('Gravação bloqueada. Exporte os dados e recarregue a página.');
  const next=D.clone(state);const result=fn(next);state=D.persist(localStorage,key,state,next);ui.dirty=false;updateShell();if(message)toast(message);return result;
}
function safeCommit(fn,message){try{return commit(fn,message);}catch(e){toast(e.message);return null;}}
function navigate(hash){if(location.hash===hash)render();else location.hash=hash;}
function heading(title,description,actions='',eyebrow='GESTÃO DE DORMENTES'){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function btn(label,action,ico='plus',primary=false,extra=''){return `<button type="button" class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${icon(ico)}${label}</button>`;}
function link(label,href,ico='arrow',primary=false){return `<a class="button ${primary?'primary':''}" href="${esc(href)}">${icon(ico)}${label}</a>`;}
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const conditionBadge=i=>badge(i.condition,i.condition==='Sem avarias aparentes'?'good':i.condition==='Restrito'?'bad':i.condition==='Requer avaliação'?'warn':'');
function statusBadges(i){return `<div class="badges">${i.countDate===D.today()?badge('Conferido hoje','good'):badge('Conferência pendente')}${D.divergence(i)?badge('Divergência','warn'):''}${i.stock<=i.min?badge('Estoque baixo','bad'):''}</div>`;}
function empty(title,copy,action='',compact=false){return `<div class="empty ${compact?'compact':''}"><span>${icon('box')}</span><h3>${esc(title)}</h3><p>${esc(copy)}</p>${action}</div>`;}
function selectOptions(options,selected='',blank='Todos'){return `${blank!==null?`<option value="">${esc(blank)}</option>`:''}${options.map(x=>{const [val,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(val)}" ${String(val)===String(selected)?'selected':''}>${esc(label)}</option>`;}).join('')}`;}
function field(label,name,{value='',type='text',required=false,placeholder='',min='',max='',step='',help='',full=false,readonly=false}={}){return `<label class="${full?'full-width':''}"><span class="field-label">${label}${required?' <span class="required">*</span>':''}</span><input name="${name}" id="field-${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${readonly?'readonly':''} ${placeholder?`placeholder="${esc(placeholder)}"`:''} ${min!==''?`min="${min}"`:''} ${max!==''?`max="${max}"`:''} ${step!==''?`step="${step}"`:''} maxlength="${name==='notes'?2000:180}">${help?`<small class="field-help">${help}</small>`:''}</label>`;}
function selectField(label,name,options,value='',required=false,blank='Selecione'){return `<label><span class="field-label">${label}${required?' <span class="required">*</span>':''}</span><select name="${name}" id="field-${name}" ${required?'required':''}>${selectOptions(options,value,blank)}</select></label>`;}
const formError=()=>'<div id="formError" class="form-error" role="alert" hidden></div>';
function showError(e){const box=$('modal').open?$('modalError'):$('formError');if(box){box.hidden=false;box.textContent=e.message;box.scrollIntoView({block:'nearest',behavior:'smooth'});}else toast(e.message);}
function updateShell(){
  const r=route(),m=D.metrics(state);const current=r.name==='ficha'?'inventario':r.name;
  $('desktopNav').innerHTML=NAV.filter(n=>n[0]!=='dashboard'||isAdmin()).map(([id,label,ico],n)=>`${id==='dashboard'?'<div class="nav-separator"></div>':''}<a class="nav-link ${id===current?'active':''}" ${id===current?'aria-current="page"':''} href="#${id}">${icon(ico)}${label}${id==='inventario'?`<span class="count-badge">${state.items.length}</span>`:id==='relatorios'&&m.reportPending?`<span class="count-badge">${m.reportPending}</span>`:''}</a>`).join('');
  $('mobileNav').innerHTML=[['inicio','Início','grid'],['inventario','Inventário','box'],['registros','Registrar','plus'],['conferencia','Conferir','check']].map(([id,label,ico])=>`<a class="${id===current?'active ':''}${id==='registros'?'new-nav':''}" href="#${id}" ${id===current?'aria-current="page"':''}>${id==='registros'?`<span class="nav-plus">${icon(ico)}</span>`:icon(ico)}${label}</a>`).join('')+`<button type="button" data-action="menu" aria-label="Abrir outras áreas" class="${!['inicio','inventario','registros','conferencia'].includes(current)?'active':''}">${icon('menu')}Mais</button>`;
  $('breadcrumb').textContent=r.name==='ficha'?'Ficha do dormente':r.name==='conta'?'Conta e dados':NAV.find(n=>n[0]===r.name)?.[1]||'Visão geral';
  document.title=`Mariporã | ${$('breadcrumb').textContent}`;
  $('profileName').textContent=state.profile.name;$('profileRole').textContent=`${isAdmin()?'Administrador':'Funcionário'} · prévia`;
  $('avatar').textContent=state.profile.name.trim().split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase();
  $('today').textContent=new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'});
  $('connection').innerHTML=`<span class="status-dot"></span><span>${navigator.onLine?'Modo local':'Sem conexão'}</span>`;
  $('connection').setAttribute('aria-label',`${state.outbox.length} alterações locais. Abrir situação dos dados.`);
  $('footerState').textContent=demo?'Dados de demonstração':`${state.outbox.length?fmt(state.outbox.length)+' alterações locais · ':''}Salvo neste dispositivo`;
  $('demoBanner').hidden=!demo;$('storageWarning').hidden=!storageError;$('storageWarning').textContent=storageError;
  document.documentElement.dataset.theme=state.preferences.theme;document.documentElement.classList.toggle('large-text',!!state.preferences.largeText);
}
function render(preserveFocus=false){
  const active=document.activeElement,focusId=active?.id,selection=active?.selectionStart;
  updateShell();let r;try{r=route();}catch{r={name:'inicio',id:''};}
  const pages={inicio:overview,registros:()=>recordPage(r.id),inventario:()=>inventoryPage(false),conferencia:()=>inventoryPage(true),ficha:()=>detailPage(r.id),historico:historyPage,relatorios:reportsPage,dashboard:dashboardPage,tutorial:tutorialPage,conta:accountPage};
  $('page').innerHTML=(pages[r.name]||overview)();hydrateIcons();
  if(preserveFocus&&focusId){const target=$(focusId);target?.focus({preventScroll:true});if(typeof selection==='number'&&target?.setSelectionRange)try{target.setSelectionRange(selection,selection);}catch{}}
}
function metric(title,value,sub,ico,kind='',suffix=''){return `<article class="metric"><div class="metric-title">${title}<span class="metric-icon ${kind}">${icon(ico)}</span></div><strong>${fmt(value)}${suffix?`<em>${suffix}</em>`:''}</strong><small>${sub}</small></article>`;}
function overview(){
  const m=D.metrics(state),first=state.profile.name.split(' ')[0],hour=new Date().getHours(),greeting=hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';
  const cards={stock:metric('Dormentes em estoque',m.stock,`${fmt(m.lots)} identificações cadastradas`,'box','purple'),inspections:metric('Aguardando inspeção',m.pending,'Identificações sem avaliação','clipboard',''),issues:metric('Precisam de atenção',m.issues,'Com restrição ou avaliação pendente','alert','amber'),counts:metric('Conferidos hoje',m.counts,'Contagens registradas na data de hoje','check','green',`/ ${m.lots}`)};
  const oldest=state.items.filter(i=>i.arrival&&i.stock>0).sort((a,b)=>a.arrival.localeCompare(b.arrival))[0];
  return heading(`${greeting}, ${first}.`,'Cada registro conta. Acompanhe seus dormentes, da chegada à próxima inspeção.',`${btn('Ler QR Code','qr','qr')}${link('Novo registro','#registros','plus',true)}`,'CONTROLE DE MATERIAIS FERROVIÁRIOS')+
  `<div class="metrics">${state.preferences.overview.map(k=>cards[k]||'').join('')}</div>
  <section class="inspection-banner"><img class="rail-art" src="dormente.svg" alt=""><div class="banner-copy"><small>DO PÁTIO AO REGISTRO</small><h2>${m.lots?'Uma inspeção, todas as informações.':'Seu inventário começa aqui.'}</h2><p>Identifique o dormente, registre a condição observada e mantenha o histórico sempre por perto.</p></div>${link('Iniciar inspeção','#registros','arrow')}</section>
  <div class="content-grid"><section class="card"><div class="card-head"><div><h2>Inventário em resumo</h2><p>Identificação, disponibilidade e condição.</p></div><span class="pill">${fmt(m.lots)} registros</span></div>${m.lots?`<div class="summary-list">${state.items.slice(0,4).map(i=>`<a class="summary-row" href="${itemHref(i)}"><img src="dormente.svg" class="material-icon" alt=""><span class="row-copy"><b>${esc(i.name)}</b><small><span class="code">${esc(i.code)}</span> · ${esc(i.location)}</small></span><span class="row-value">${fmt(i.stock)} un.<small>${esc(i.condition)}</small></span></a>`).join('')}</div>`:empty('Nenhum dormente cadastrado','Adicione o primeiro lote ou identifique uma peça individual.',link('Cadastrar dormente','#registros','plus'),true)}<a class="card-link" href="#inventario">Abrir inventário completo ${icon('arrow')}</a></section>
  <section class="card"><div class="card-head"><div><h2>No seu radar</h2><p>Os próximos passos da operação.</p></div>${icon('alert')}</div><div class="alert-list"><div class="alert-row"><span class="alert-icon">${icon('clipboard')}</span><div><b>${m.pending?`${fmt(m.pending)} aguardando inspeção`:'Inspeções em dia'}</b><p>${m.pending?'Registre a condição física dos materiais pendentes.':'Novos registros aparecerão aqui para acompanhamento.'}</p><a href="#inventario" data-preset="pending">Ver registros ${icon('arrow')}</a></div></div><div class="alert-row"><span class="alert-icon">${icon('file')}</span><div><b>${m.reportPending?`${fmt(m.reportPending)} inspeções sem relatório`:'Relatórios organizados'}</b><p>Gere uma planilha ou um PDF com os dados registrados.</p><a href="#relatorios">Acessar relatórios ${icon('arrow')}</a></div></div><div class="alert-row"><span class="alert-icon">${icon('clock')}</span><div><b>${oldest?`Há ${D.daysSince(oldest.arrival)} dias no depósito`:'Acompanhe o tempo no depósito'}</b><p>${oldest?`${esc(oldest.code)} · Chegada em ${date(oldest.arrival)}.`:'Informe a data de chegada para localizar os lotes mais antigos.'}</p>${oldest?`<a href="${itemHref(oldest)}">Consultar lote ${icon('arrow')}</a>`:''}</div></div></div></section></div>
  <div class="helper-strip">${icon('shield')}<p><b>Seu trabalho fica salvo neste dispositivo.</b> Faça uma cópia de segurança em Conta e dados.</p>${link('Gerenciar dados','#conta','arrow')}</div>
  ${!state.items.length&&!demo?`<div class="section-heading"><p>Quer conhecer os fluxos antes de cadastrar?</p><button class="text-button" data-action="demo">Explorar dados de exemplo ${icon('arrow')}</button></div>`:''}
  ${isAdmin()?'<button class="text-button" data-action="overview">Personalizar indicadores da visão geral</button>':''}`;
}
function filters(conference){const f=conference?ui.conference:ui.inventory;return `<div class="toolbar"><label class="search-field"><span>Buscar identificação</span><div class="search-wrap">${icon('search')}<input id="listSearch" data-filter="${conference?'conference':'inventory'}" data-key="search" value="${esc(f.search)}" placeholder="Código, material ou localização"></div></label>${!conference?`<label><span>Material</span><select id="listType" data-filter="inventory" data-key="type">${selectOptions(D.TYPES,f.type,'Todos os materiais')}</select></label>`:''}<label><span>Situação</span><select id="listStatus" data-filter="${conference?'conference':'inventory'}" data-key="status">${selectOptions([['pending','Aguardando inspeção'],['issues','Requer atenção'],['diff','Divergência'],['low','Estoque baixo'],['today','Conferido hoje']],f.status,'Todas as situações')}</select></label></div>`;}
function inventoryPage(conference){
  const f=conference?ui.conference:ui.inventory,items=state.items.filter(i=>D.matches(i,f)),pages=Math.max(1,Math.ceil(items.length/8));f.page=Math.min(f.page,pages);
  const list=items.slice((f.page-1)*8,f.page*8);
  return heading(conference?'Conferência de estoque':'Inventário',conference?'Compare a quantidade física com a registrada. O saldo só muda ao registrar uma movimentação.':'Consulte os dormentes, acompanhe a condição e encontre cada lote no pátio.',conference?btn('Localizar por QR','qr','qr'):link('Novo registro','#registros','plus',true))+
  (conference?`<div class="metrics">${metric('Conferidos hoje',D.metrics(state).counts,'Somente contagens de hoje','check','green')}${metric('Divergências',D.metrics(state).diff,'Comparadas ao saldo na conferência','move','amber')}${metric('Estoque baixo',D.metrics(state).low,'Abaixo ou igual ao mínimo','alert')}${metric('Identificações',state.items.length,'Lotes e unidades individuais','box','purple')}</div>`:'')+
  `<section class="card">${filters(conference)}${items.length?`<div class="table-scroll data-table"><table><thead><tr><th>Material / código</th><th>Localização</th><th>Estoque</th>${!conference?'<th>Contagem atual</th>':''}<th>${conference?'Última contagem':'Condição'}</th><th>${conference?'Situação':'Armazenamento'}</th>${!conference?'<th>Situação</th>':''}<th>Ações</th></tr></thead><tbody>${list.map(i=>`<tr><td><div class="material-cell"><img class="material-icon" src="dormente.svg" alt=""><div><a href="${itemHref(i)}"><b>${esc(i.name)}</b></a><small class="code">${esc(i.code)}</small></div></div></td><td>${esc(i.location)}<small>${i.scope==='lot'?'Lote':'Unidade'} · ${esc(i.type)}</small></td><td><span class="number">${fmt(i.stock)} un.</span><small>Mín. ${fmt(i.min)}</small></td>${!conference?`<td>${i.count===null?'Sem contagem':fmt(i.count)+' un.'}<small>${i.countDate?date(i.countDate):'Data não informada'}</small></td>`:''}<td>${conference?`${i.count===null?'Sem contagem':`${fmt(i.count)} un.`}<small>${i.countDate?date(i.countDate):'Data não informada'}</small>`:conditionBadge(i)}</td><td>${conference?statusBadges(i):`${D.daysSince(i.arrival)===null?'Não informado':D.daysSince(i.arrival)+' dias'}<small>${i.arrival?'Chegada: '+date(i.arrival):'Complete a ficha'}</small>`}</td>${!conference?`<td>${statusBadges(i)}</td>`:''}<td><div class="row-actions">${conference?btn('Conferir','count','check',false,`data-id="${esc(i.id)}"`):`<a class="button small" href="${itemHref(i)}">Ver ficha ${icon('chevron')}</a>`}</div></td></tr>`).join('')}</tbody></table></div><div class="mobile-cards">${list.map(i=>`<article class="inventory-card"><header><img class="material-icon" src="dormente.svg" alt=""><div><a href="${itemHref(i)}"><b>${esc(i.name)}</b></a><small class="code">${esc(i.code)}</small></div><span class="stock-number">${fmt(i.stock)}<small>unidades</small></span></header><div class="mobile-details"><div><small>LOCALIZAÇÃO</small>${esc(i.location)}</div><div><small>${conference?'CONTAGEM FÍSICA':'NO DEPÓSITO'}</small>${conference?(i.count===null?'Sem contagem':`${fmt(i.count)} un. · ${i.countDate?date(i.countDate):'Sem data'}`):i.arrival?`${D.daysSince(i.arrival)} dias`:'Data não informada'}</div>${!conference?`<div><small>CONTAGEM FÍSICA</small>${i.count===null?'Sem contagem':fmt(i.count)+' un.'}</div><div><small>DATA DA CONTAGEM</small>${i.countDate?date(i.countDate):'Não informada'}</div>`:''}</div><div class="badges">${conditionBadge(i)}</div>${statusBadges(i)}<div class="button-row">${link('Ver ficha',itemHref(i),'file')}${conference?btn('Conferir','count','check',true,`data-id="${esc(i.id)}"`):link('Inspecionar',navHref('registros',i.id),'clipboard',true)}</div></article>`).join('')}</div><div class="table-footer"><span>${(f.page-1)*8+1}-${Math.min(f.page*8,items.length)} de ${fmt(items.length)} identificações</span><div class="pagination"><button class="icon-button" data-action="page" data-list="${conference?'conference':'inventory'}" data-page="${f.page-1}" ${f.page===1?'disabled':''} aria-label="Página anterior">${icon('left')}</button><span>${f.page} / ${pages}</span><button class="icon-button" data-action="page" data-list="${conference?'conference':'inventory'}" data-page="${f.page+1}" ${f.page===pages?'disabled':''} aria-label="Próxima página">${icon('chevron')}</button></div></div>`:empty(state.items.length?'Nenhum resultado encontrado':'Seu inventário está vazio',state.items.length?'Ajuste a busca ou limpe os filtros.':'Cadastre um lote ou uma unidade para começar.',state.items.length?btn('Limpar filtros','clearFilters','search'):link('Novo registro','#registros','plus',true))}</section>`;
}
function inspectionFields(i){return `<div class="form-grid">${field('Data de inspeção','inspectionDate',{value:D.today(),type:'date',required:true,min:i?.arrival||'',max:D.today()})}${field('Quantidade observada','inspectionQuantity',{value:i?Math.min(i.stock,1):1,type:'number',required:true,min:1,step:1,help:'Informe quantas unidades foram efetivamente observadas.'})}${selectField('Condição observada','condition',D.CONDITIONS.slice(1),'',true)}<div class="full-width"><span class="field-label">Ocorrências observadas</span><div class="checklist">${D.DEFECTS.map((d,n)=>`<label class="check-option"><input type="checkbox" name="defects" value="${esc(d)}" id="defect-${n}">${esc(d)}</label>`).join('')}</div></div><label class="full-width"><span class="field-label">Observações da inspeção</span><textarea name="inspectionNotes" id="inspectionNotes" maxlength="2000" placeholder="Descreva a ocorrência, a região afetada e outros detalhes relevantes."></textarea><small class="field-help">Obrigatório quando selecionar Outros.</small></label></div><div class="note">Registre apenas o que foi observado. Uma inspeção parcial não classifica automaticamente todas as unidades do lote. A liberação para uso depende de avaliação técnica.</div>`;}
function recordPage(id){
  const i=id?itemById(id):null;if(id&&!i)return notFound();
  return heading(i?'Nova inspeção':'Novo registro',i?`Adicione uma avaliação a ${i.code}. As inspeções anteriores serão preservadas.`:'Identifique o dormente ou lote e registre as informações da chegada.',btn('Ler QR Code','qr','qr'))+
  `<div class="form-layout"><form id="recordForm" class="card" data-item="${esc(i?.id||'')}">${i?`<section class="form-section"><h2>${esc(i.name)}</h2><p>${esc(i.code)} · ${esc(i.location)} · ${fmt(i.stock)} unidades disponíveis</p><a href="${itemHref(i)}" class="text-button">Consultar ficha completa ${icon('arrow')}</a></section>`:`<section class="form-section"><h2><span class="step-num">1</span>Identificação</h2><p>O código identifica um lote ou uma única peça. Escolha antes de cadastrar.</p><div class="form-grid"><div class="full-width"><span class="field-label">O que está sendo identificado? <span class="required">*</span></span><div class="radio-cards"><label class="radio-card"><input type="radio" name="scope" value="lot" checked><span><b>Lote de dormentes</b><small>Um código para várias unidades</small></span></label><label class="radio-card"><input type="radio" name="scope" value="unit"><span><b>Unidade individual</b><small>Um código para uma peça</small></span></label></div></div>${field('Código de identificação','code',{value:ui.prefill,required:true,placeholder:'Ex.: DOR-MAD-001'})}${selectField('Material','type',D.TYPES,'Madeira',true)}${field('Descrição','name',{required:true,placeholder:'Ex.: Dormente de eucalipto',full:true})}${field('Classe','class',{required:true,placeholder:'Classificação informada pela equipe'})}${field('Espécie','species',{required:true,placeholder:'Ex.: Eucalipto',help:'Se desconhecida, registre Não identificada.'})}<div class="full-width"><span class="field-label">Dimensões, em centímetros <span class="required">*</span></span><div class="form-grid three">${field('Comprimento','length',{type:'number',required:true,min:.01,step:'any',placeholder:'280'})}${field('Largura','width',{type:'number',required:true,min:.01,step:'any',placeholder:'24'})}${field('Altura','height',{type:'number',required:true,min:.01,step:'any',placeholder:'16'})}</div></div></div></section><section class="form-section"><h2><span class="step-num">2</span>Chegada e localização</h2><p>Esses dados alimentam o inventário e o tempo de armazenamento.</p><div class="form-grid">${field('Localização','location',{required:true,placeholder:'Pátio, setor e posição',full:true})}${field('Quantidade de entrada','stock',{type:'number',value:1,required:true,min:1,step:1})}${field('Estoque mínimo','min',{type:'number',value:0,required:true,min:0,step:1,help:'Usado somente para alertas de estoque.'})}${field('Data de chegada','arrival',{type:'date',value:D.today(),required:true,max:D.today()})}${field('Origem / fornecedor','supplier',{required:true,placeholder:'Empresa ou origem do lote'})}</div></section>`}
  <section class="form-section"><h2><span class="step-num">${i?'1':'3'}</span>Inspeção física</h2><p>Registre a condição e as ocorrências observadas nesta inspeção.</p>${!i?'<label class="inline-check"><input type="checkbox" id="includeInspection" name="includeInspection" checked>Registrar a inspeção agora</label>':''}<fieldset id="inspectionFields" style="border:0;padding:0;margin:20px 0 0;min-width:0">${inspectionFields(i)}</fieldset>${formError()}</section><div class="form-actions"><p>* Campos obrigatórios</p><div class="button-row">${link('Cancelar',i?itemHref(i):'#inventario','left')}<button type="submit" class="button primary">${icon('check')}${i?'Salvar inspeção':'Salvar registro'}</button></div></div></form>
  <aside class="form-side"><div class="aside-note">${icon('qr')}<h3>Já tem uma etiqueta?</h3><p>Leia o QR Code para localizar a identificação. Se ela já existir, uma nova inspeção será vinculada à ficha.</p><button class="text-button" data-action="qr">Ler ou digitar código ${icon('arrow')}</button></div><div class="aside-note">${icon('clipboard')}<h3>Um registro bem feito</h3><ol><li>Confira a identificação na etiqueta.</li><li>Informe a localização no pátio.</li><li>Registre apenas a quantidade observada.</li><li>Descreva as ocorrências encontradas.</li></ol></div></aside></div>`;
}
function notFound(){return heading('Registro não encontrado','O código não está neste dispositivo.')+empty('Não encontramos essa identificação','Confira o código ou consulte o inventário.',link('Abrir inventário','#inventario','box'));}
function detailPage(id){
  const i=itemById(id);if(!i)return notFound();const history=state.history.filter(e=>e.itemId===i.id),inspections=state.inspections.filter(e=>e.itemId===i.id).sort((a,b)=>b.date.localeCompare(a.date)||b.at.localeCompare(a.at));
  const data=[['Identificação',i.scope==='lot'?'Lote':'Unidade individual'],['Material',i.type],['Classe',i.class],['Espécie',i.species],['Dimensões (C × L × A)',[i.length,i.width,i.height].every(Boolean)?`${i.length} × ${i.width} × ${i.height} cm`:'Não informadas'],['Localização',i.location],['Origem / fornecedor',i.supplier],['Data de chegada',date(i.arrival)],['Tempo no depósito',i.arrival?`${D.daysSince(i.arrival)} dias`:'Não informado'],['Estoque disponível',`${fmt(i.stock)} unidades`],['Estoque mínimo',`${fmt(i.min)} unidades`],['Última contagem',i.count===null?'Sem contagem':`${fmt(i.count)} un. · ${i.countDate?date(i.countDate):'Sem data'}`]];
  return heading('Ficha do dormente',`${i.code} · Identificação e acompanhamento`,link('Voltar ao inventário','#inventario','left'))+
  `<section class="card detail-hero"><img class="material-icon" src="dormente.svg" alt=""><div class="detail-title"><h2>${esc(i.name)}</h2><p class="code">${esc(i.code)}</p><div class="badges" style="margin-top:8px">${conditionBadge(i)}${badge(i.scope==='lot'?'Lote':'Unidade')}</div></div><div class="button-row">${btn('Movimentar','move','move',false,`data-id="${esc(i.id)}"`)}${link('Nova inspeção',navHref('registros',i.id),'clipboard',true)}</div></section>
  <div class="detail-columns"><div><section class="card card-pad"><div class="section-heading"><h2>Dados de identificação</h2>${isAdmin()?`<button class="text-button" data-action="edit" data-id="${esc(i.id)}">${icon('edit')} Corrigir</button>`:''}</div><dl class="details-grid">${data.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${i.notes?`<div class="note">${esc(i.notes)}</div>`:''}<div class="note">Tempo de armazenamento é contado desde a chegada. Não representa validade ou prazo de liberação.</div>${statusBadges(i)}<div class="button-row" style="margin-top:18px">${btn('Conferir quantidade','count','check',false,`data-id="${esc(i.id)}"`)}${btn('Copiar código','copyCode','qr',false,`data-id="${esc(i.id)}"`)}</div></section>
  <section class="card card-pad" style="margin-top:22px"><div class="section-heading"><h2>Inspeções realizadas</h2><span class="pill">${inspections.length}</span></div>${inspections.length?`<ol class="timeline">${inspections.map(e=>`<li><small>${date(e.date)} · ${esc(e.user)}</small><div style="margin:7px 0">${conditionBadge(e)}</div><p>${fmt(e.quantity)} unidades observadas${e.quantity<i.stock?' · Inspeção parcial do lote':''}</p><p>${esc(e.defects.join(', ')||'Sem ocorrências registradas.')}</p>${e.notes?`<p>${esc(e.notes)}</p>`:''}<small>${e.reportedAt?'Incluída em relatório em '+dateTime(e.reportedAt):'Pendente de inclusão em relatório'}</small></li>`).join('')}</ol>`:empty('Nenhuma inspeção registrada','Registre a condição observada para iniciar o acompanhamento.',link('Inspecionar',navHref('registros',i.id),'clipboard'),true)}</section></div>
  <section class="card card-pad"><div class="section-heading"><h2>Histórico desta identificação</h2><span class="pill">${history.length} eventos</span></div>${history.length?timeline(history):'<p class="small-copy">Nenhum evento disponível.</p>'}</section></div>`;
}
function timeline(events){return `<ol class="timeline">${events.map(e=>`<li><small>${dateTime(e.at)} · ${esc(e.user)}</small><div><b>${esc(e.action)}</b>${e.code?` <span class="code">${esc(e.code)}</span>`:''}</div><p>${esc(e.details)}</p>${e.before?`<details><summary>Ver dados anteriores e corrigidos</summary><pre>${esc(JSON.stringify({antes:e.before,depois:e.after},null,2))}</pre></details>`:''}</li>`).join('')}</ol>`;}
function historyPage(){
  const f=ui.history;const all=state.history.filter(e=>(!f.search||D.fold([e.code,e.details,e.action].join(' ')).includes(D.fold(f.search)))&&(!f.user||e.user===f.user)&&(!f.action||e.action===f.action)&&(!f.from||localEventDay(e.at)>=f.from)&&(!f.to||localEventDay(e.at)<=f.to));const pages=Math.max(1,Math.ceil(all.length/20));f.page=Math.min(f.page,pages);
  return heading('Histórico','Acompanhe quem registrou, o que mudou e quando. Correções mantêm os dados anteriores.')+`<section class="card"><div class="toolbar"><label class="search-field"><span>Código ou atividade</span><div class="search-wrap">${icon('search')}<input id="historySearch" value="${esc(f.search)}" data-filter="history" data-key="search" placeholder="Buscar no histórico"></div></label><label><span>Responsável</span><select id="historyUser" data-filter="history" data-key="user">${selectOptions([...new Set(state.history.map(e=>e.user))],f.user)}</select></label><label><span>Ação</span><select id="historyAction" data-filter="history" data-key="action">${selectOptions([...new Set(state.history.map(e=>e.action))],f.action)}</select></label><label><span>De</span><input id="historyFrom" type="date" value="${f.from}" data-filter="history" data-key="from"></label><label><span>Até</span><input id="historyTo" type="date" value="${f.to}" data-filter="history" data-key="to"></label></div>${all.length?`<div class="card-pad">${timeline(all.slice((f.page-1)*20,f.page*20))}</div><div class="table-footer"><span>${fmt(all.length)} atividades encontradas</span><div class="pagination"><button class="icon-button" data-action="page" data-list="history" data-page="${f.page-1}" ${f.page===1?'disabled':''} aria-label="Página anterior">${icon('left')}</button><span>${f.page} / ${pages}</span><button class="icon-button" data-action="page" data-list="history" data-page="${f.page+1}" ${f.page===pages?'disabled':''} aria-label="Próxima página">${icon('chevron')}</button></div></div>`:empty('Nenhuma atividade encontrada','Os cadastros, inspeções, contagens e movimentações aparecerão aqui.')}</section>`;
}
function localEventDay(at){const d=new Date(at);return Number.isNaN(d.getTime())?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function distribution(groups){const max=Math.max(1,...groups.map(x=>x[1]));return groups.length?`<div class="distribution">${groups.map(([label,val])=>`<div class="distribution-row"><div><span>${esc(label)}</span><b>${fmt(val)} un.</b></div><div class="track"><i style="width:${val/max*100}%"></i></div></div>`).join('')}</div>`:'<div class="note">Sem dados para exibir.</div>';}
function movementChart(rows){const max=Math.max(1,...rows.flatMap(x=>[x.entry,x.exit]));return `<div class="legend"><span>Entradas</span><span>Saídas</span></div><div class="bars" role="img" aria-label="${esc(rows.map(r=>`${r.label}: ${r.entry} entradas e ${r.exit} saídas`).join('; '))}">${rows.map(r=>`<div class="bar-group" title="${esc(r.label)}: ${r.entry} entradas / ${r.exit} saídas"><span style="height:${r.entry/max*100}%"></span><span class="out" style="height:${r.exit/max*100}%"></span><small>${esc(r.label)}</small></div>`).join('')}</div><details style="margin-top:18px"><summary class="small-copy">Ver valores em tabela</summary><div class="table-scroll"><table><thead><tr><th>Período</th><th>Entradas</th><th>Saídas</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${fmt(r.entry)}</td><td>${fmt(r.exit)}</td></tr>`).join('')}</tbody></table></div></details>`;}
function dashboardPage(){if(!isAdmin())return heading('Dashboard administrativo','Disponível ao perfil de administrador.')+empty('Área administrativa','O perfil atual pode registrar, consultar e exportar dados.',link('Voltar à visão geral','#inicio','grid'));
  const m=D.metrics(state),inspected=state.items.filter(i=>i.condition!=='Não inspecionado').length,affected=state.items.filter(D.issues).length,years=[...new Set([new Date().getFullYear(),...state.movements.map(e=>Number(e.date.slice(0,4)))])].sort((a,b)=>b-a);
  return heading('Dashboard','Indicadores para acompanhar o estoque e planejar as próximas inspeções.',link('Gerar relatório','#relatorios','file'))+
  `<div class="metrics">${metric('Estoque atual',m.stock,'Total de unidades registradas','box','purple')}${metric('Identificações avaliadas',inspected,'Lotes ou unidades com inspeção','clipboard','green')}${metric('Condição requer atenção',affected,inspected?`${Math.round(affected/inspected*100)}% das identificações avaliadas`:'Sem inspeções para calcular o índice','alert','amber')}${metric('Divergências de contagem',m.diff,'Exigem revisão do saldo físico','move')}</div><div class="dashboard-filters"><label>Agrupar por<select id="chartPeriod" data-filter="dashboard" data-key="period">${selectOptions([['month','Mês'],['semester','Semestre'],['year','Ano']],ui.dashboard.period,null)}</select></label><label>Ano<select id="chartYear" data-filter="dashboard" data-key="year">${selectOptions(years,ui.dashboard.year,null)}</select></label></div><div class="content-grid"><section class="card chart-card"><h2>Entradas e saídas</h2><p>Unidades movimentadas no período selecionado. Ajustes não entram no gráfico.</p>${movementChart(D.periodBuckets(state,ui.dashboard.period,ui.dashboard.year))}</section><section class="card chart-card"><h2>Condição das identificações</h2><p>Última inspeção por identificação. Não representa o total de peças danificadas.</p>${distribution(D.CONDITIONS.map(c=>[c,state.items.filter(i=>i.condition===c).length]).filter(x=>x[1])).replaceAll(' un.',' ident.')}</section></div><div class="content-grid"><section class="card chart-card"><h2>Estoque por espécie</h2><p>Unidades de madeira disponíveis no inventário.</p>${distribution(D.grouped(state.items.filter(i=>i.type==='Madeira'),'species'))}</section><section class="card chart-card"><h2>Estoque por classe</h2><p>Unidades disponíveis em todas as classes.</p>${distribution(D.grouped(state.items,'class'))}</section></div>`;
}
function reportsPage(){const f=ui.reports;let data,error='';try{data=D.reportData(state,f);}catch(e){data={items:[],inspections:[],movements:[]};error=e.message;}
  return heading('Relatórios','Transforme os registros em planilha ou PDF, com os indicadores que você precisa.',`<span class="badge ${D.metrics(state).reportPending?'warn':'good'}">${D.metrics(state).reportPending} inspeções sem relatório</span>`)+
  `<div class="report-layout"><section class="card report-options"><h2>Defina o conteúdo</h2><div class="form-grid"><label><span class="field-label">Inspeções a partir de</span><input id="reportFrom" type="date" value="${f.from}" data-filter="reports" data-key="from"></label><label><span class="field-label">Até</span><input id="reportTo" type="date" value="${f.to}" data-filter="reports" data-key="to"></label><label class="full-width"><span class="field-label">Material</span><select id="reportType" data-filter="reports" data-key="type">${selectOptions(D.TYPES,f.type,'Todos os materiais')}</select></label><label class="full-width"><span class="field-label">Localização</span><input id="reportLocation" value="${esc(f.location)}" placeholder="Todos os locais" data-filter="reports" data-key="location"></label></div><div class="note">O período filtra inspeções, contagens e movimentações. O estoque apresentado é o saldo atual, sem reconstrução histórica.</div><h3>Gráficos no PDF</h3>${[['condition','Condição das identificações'],['species','Estoque por espécie'],['class','Estoque por classe'],['movement','Entradas e saídas no período']].map(([v,l])=>`<label class="inline-check"><input type="checkbox" data-chart="${v}" ${f.charts.includes(v)?'checked':''}>${l}</label>`).join('')}<div class="button-row" style="margin-top:20px">${btn('Planilha Excel','xlsx','download',false,error?'disabled':'')}${btn('Gerar PDF','pdf','file',true,error?'disabled':'')}</div><button class="text-button" data-action="csv" ${error?'disabled':''}>Baixar inventário em CSV</button>${error?`<div class="form-error" role="alert">${esc(error)}</div>`:''}</section>
  <section class="report-preview"><div class="report-letterhead"><div><h3>Mariporã</h3><p>PROJETO PORÃ · INSPEÇÃO DE DORMENTES</p></div><img src="app-icon.svg" alt=""></div><span class="eyebrow">PRÉVIA DO CONTEÚDO</span><h2>Relatório de acompanhamento</h2><p class="small-copy">${f.from?date(f.from):'Desde o primeiro registro'} até ${f.to?date(f.to):'hoje'} · ${esc(f.type||'Todos os materiais')}</p><div class="report-stats"><div><strong>${fmt(data.items.reduce((a,i)=>a+i.stock,0))}</strong><small>unidades em estoque atual</small></div><div><strong>${fmt(data.inspections.length)}</strong><small>inspeções no período</small></div><div><strong>${fmt(data.movements.length)}</strong><small>movimentações no período</small></div></div><h3>O que será incluído</h3><div class="status-table" style="margin:18px 0"><div><span>Identificação e saldo atual</span>${badge(data.items.length+' registros','good')}</div><div><span>Inspeções e ocorrências</span>${badge(data.inspections.length+' inspeções','good')}</div><div><span>Gráficos selecionados</span>${badge(f.charts.length+' gráficos','good')}</div><div><span>Movimentações e conferências</span>${badge('Rastreabilidade','good')}</div></div><div class="note">Modelo de acompanhamento do projeto, sujeito à validação da equipe. Não substitui laudo técnico ou formulário oficial.</div><p class="small-copy">Os arquivos são gerados com os dados salvos neste dispositivo e podem ser produzidos sem conexão após o carregamento do app.</p></section></div>`;
}
const GUIDES=[['clipboard','Cadastrar e inspecionar','Identifique o material e registre a condição observada.',['Abra Registros e escolha lote ou unidade individual.','Preencha código, material, classe, espécie e dimensões.','Informe quantidade, localização, origem e data de chegada.','Selecione a condição observada, as ocorrências e a quantidade inspecionada.','Salve. A ficha reúne o cadastro e cada inspeção.']],['qr','Ler uma identificação','Acesse uma ficha usando a etiqueta do dormente.',['Toque em Ler QR Code.','Permita a câmera quando o navegador solicitar.','Aponte para a etiqueta. Se a leitura não estiver disponível, digite o código.','Uma identificação conhecida abre a nova inspeção; uma nova preenche o código do cadastro.']],['check','Conferir o estoque','Compare a quantidade registrada com a encontrada no pátio.',['Abra Conferência e encontre a identificação.','Toque em Conferir e informe a quantidade física.','Salve a contagem. Uma divergência fica destacada.','Uma contagem não altera o saldo. Registre uma movimentação ou peça um ajuste ao administrador.']],['move','Registrar movimentações','Acompanhe entradas e saídas com motivo e responsável.',['Abra uma ficha no Inventário e toque em Movimentar.','Escolha entrada ou saída e informe a quantidade.','Informe a data e o motivo ou destino.','Confira o saldo resultante e salve. A contagem anterior fica no histórico.']],['file','Gerar relatórios','Exporte informações da operação para Excel, CSV ou PDF.',['Abra Relatórios e defina o intervalo e os filtros.','Escolha os gráficos para o PDF.','Clique em Planilha Excel ou Gerar PDF.','O saldo é sempre o atual; o período filtra apenas os eventos.']],['shield','Proteger seus registros','Mantenha uma cópia fora do navegador.',['Abra Conta e dados e exporte um backup JSON.','Guarde o arquivo em um local seguro.','Para restaurar em outro dispositivo, use Importar backup.','No modo local não há envio para servidor, mesmo quando a conexão volta.']]];
function tutorialPage(){return heading('Um guia para cada etapa','Orientações rápidas para usar o Mariporã no computador e no pátio.',btn('Baixar manual em PDF','manual','download'))+`<div class="tutorial-grid">${GUIDES.map(([ico,title,desc,steps])=>`<article class="card tutorial-card"><span class="tutorial-symbol">${icon(ico)}</span><h2>${title}</h2><p>${desc}</p><details><summary>Ver passo a passo</summary><ol>${steps.map(s=>`<li>${s}</li>`).join('')}</ol></details></article>`).join('')}</div><div class="helper-strip" style="margin-top:24px">${icon('volume')}<p><b>Prefere ouvir?</b> Leia as instruções desta página em voz alta. Você também pode usar o leitor de tela do dispositivo.</p>${btn('Ouvir guia','speak','volume')}${btn('Parar leitura','stopSpeak','x')}</div><div class="note">Os vídeos curtos serão acrescentados depois da validação dos fluxos com a equipe.</div>`;}
function accountPage(){return heading('Conta e dados','Identificação de trabalho, preferências de leitura e proteção dos seus registros.')+`<div class="content-grid"><div><form id="profileForm" class="card card-pad"><h2>Identificação local</h2><div class="note warning">Versão de desenvolvimento. Este perfil identifica os registros neste dispositivo. A autenticação institucional e o controle real de permissões ainda precisam do servidor.</div><div class="form-grid">${field('Nome do responsável','profileName',{value:state.profile.name,required:true})}${field('E-mail institucional','email',{value:state.profile.email,type:'email',placeholder:'nome@instituicao.com.br',help:'Informação local, ainda não verificada.'})}${selectField('Perfil da prévia','role',[['admin','Administrador'],['user','Funcionário']],state.profile.role,true,null)}</div>${formError()}<div class="button-row" style="margin-top:20px"><button type="submit" class="button primary">${icon('check')}Salvar identificação</button></div></form><section class="card card-pad" style="margin-top:22px"><h2>Aparência e acessibilidade</h2><div class="setting-row"><div><b>Tema da interface</b><p>Escolha o melhor contraste para o ambiente.</p></div><button class="button" data-action="theme">${icon(state.preferences.theme==='dark'?'sun':'moon')}${state.preferences.theme==='dark'?'Modo claro':'Modo escuro'}</button></div><div class="setting-row"><div><b>Texto ampliado</b><p>Aumenta a tipografia em todas as telas.</p></div><button class="button" data-action="largeText" aria-pressed="${!!state.preferences.largeText}">${state.preferences.largeText?'Desativar':'Ativar'}</button></div><div class="setting-row"><div><b>Instalar no dispositivo</b><p>Use o menu do navegador e escolha Instalar app ou Adicionar à tela inicial.</p></div>${btn('Instalar','install','download')}</div></section></div>
  <div><section class="card card-pad"><h2>Seus dados, por perto</h2><p class="small-copy" style="margin-top:10px">${fmt(state.items.length)} identificações · ${fmt(state.inspections.length)} inspeções · ${fmt(state.history.length)} atividades</p><div class="note">Este dispositivo guarda os registros. Limpar os dados do navegador pode removê-los. Exporte um backup regularmente.</div><div class="button-row">${btn('Exportar backup','backup','download',true)}${btn('Importar backup','import','upload')}</div>${storageError?`<div style="margin-top:12px">${btn('Exportar dados originais','rawBackup','download')}</div>`:''}<div class="setting-row"><div><b>${fmt(state.outbox.length)} alterações locais</b><p>Aguardam uma integração com o servidor.</p></div><button class="text-button" data-action="pending">Ver fila ${icon('arrow')}</button></div></section><section class="card card-pad" style="margin-top:22px"><h2>Integrações da próxima etapa</h2><div class="status-table" style="margin-top:18px">${[['Login institucional','Pendente'],['Recuperação de senha','Pendente'],['Gestão de usuários','Pendente'],['Base compartilhada / sincronização','Pendente']].map(([a,b])=>`<div><span>${a}</span>${badge(b,'warn')}</div>`).join('')}</div><p class="small-copy" style="margin-top:18px">As credenciais da primeira versão permanecem preservadas no navegador. Não são enviadas nem usadas como autenticação nesta prévia.</p></section><section class="card card-pad" style="margin-top:22px"><h2>Conhecer a interface</h2><p class="small-copy" style="margin:10px 0">Explore dados fictícios em um ambiente separado dos seus registros.</p>${btn(demo?'Voltar aos meus dados':'Abrir demonstração',demo?'exitDemo':'demo','grid')}</section></div></div><section class="card card-pad"><h2>Uso e privacidade desta versão</h2><p class="small-copy" style="margin-top:12px;line-height:1.9">Os dados de operação e o nome informado ficam neste navegador. A câmera é usada somente durante a leitura do QR Code; imagens e vídeo não são armazenados. Backups e relatórios contêm os dados exportados e devem ser compartilhados apenas com as pessoas responsáveis. Nenhum registro é enviado automaticamente a um servidor nesta versão. Termos institucionais e política de privacidade definitivos dependem da equipe responsável antes do uso em produção.</p></section>`;}

function openModal(title,subtitle,body){stopScanner();modalReturnFocus=document.activeElement;$('modalContent').innerHTML=`<div class="modal-head"><div><h2 id="modalTitle">${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Fechar janela">${icon('x')}</button></div><div class="modal-body">${body}<div id="modalError" class="form-error" role="alert" hidden></div></div>`;if(!$('modal').open)$('modal').showModal();}
function closeModal(){$('modal').close();}
function countDialog(id){const i=itemById(id);if(!i)return;openModal('Conferir quantidade',`${i.code} · ${i.location}`,`<form id="countForm" data-item="${esc(i.id)}"><div class="note">Estoque registrado: <strong>${fmt(i.stock)} unidades</strong></div>${field('Quantidade encontrada','quantity',{type:'number',required:true,min:0,step:1,placeholder:'Informe a contagem física',max:i.scope==='unit'?1:''})}<label><span class="field-label">Observações</span><textarea name="note" maxlength="1000" placeholder="Detalhes da conferência"></textarea></label><p class="small-copy">Uma divergência será registrada sem alterar automaticamente o saldo.</p><div class="modal-actions">${btn('Cancelar','close','x')}<button class="button primary" type="submit">${icon('check')}Salvar contagem</button></div></form>`);$('field-quantity')?.focus();}
function movementDialog(id){const i=itemById(id);if(!i)return;openModal('Movimentar estoque',`${i.code} · Saldo: ${fmt(i.stock)} unidades`,`<form id="movementForm" data-item="${esc(i.id)}"><div class="form-grid">${selectField('Movimentação','kind',[['entry','Entrada'],['exit','Saída'],...(isAdmin()?[['adjustment','Ajustar saldo (administrador)']]:[])],'exit',true,null)}${field('Quantidade','quantity',{type:'number',required:true,min:1,step:1})}${field('Data da movimentação','date',{type:'date',value:D.today(),min:i.arrival||'',max:D.today(),required:true})}<label class="full-width"><span class="field-label">Motivo / destino <span class="required">*</span></span><textarea name="note" required maxlength="1500" placeholder="Informe a origem, o destino ou a justificativa do ajuste"></textarea></label></div><div id="movementHelp" class="note">Entradas e saídas alteram o saldo. Após movimentar, será necessária uma nova conferência.</div><div class="modal-actions">${btn('Cancelar','close','x')}<button class="button primary" type="submit">${icon('check')}Salvar movimentação</button></div></form>`);}
function editDialog(id){if(!isAdmin()){toast('A correção requer o perfil de administrador.');return;}const i=itemById(id);if(!i)return;openModal('Corrigir identificação',`${i.code} · A justificativa e os dados anteriores ficam no histórico.`,`<form id="editForm" data-item="${esc(i.id)}"><div class="form-grid">${field('Descrição','name',{value:i.name,required:true,full:true})}${field('Localização','location',{value:i.location,required:true})}${field('Classe','class',{value:i.class,required:true})}${field('Espécie','species',{value:i.species,required:i.type==='Madeira'})}${field('Origem / fornecedor','supplier',{value:i.supplier,required:true})}${field('Data de chegada','arrival',{value:i.arrival,type:'date',required:true,max:D.today()})}${field('Estoque mínimo','min',{value:i.min,type:'number',required:true,min:0,step:1})}${field('Comprimento (cm)','length',{value:i.length,type:'number',required:true,min:.01,step:'any'})}${field('Largura (cm)','width',{value:i.width,type:'number',required:true,min:.01,step:'any'})}${field('Altura (cm)','height',{value:i.height,type:'number',required:true,min:.01,step:'any'})}<label class="full-width"><span class="field-label">Justificativa <span class="required">*</span></span><textarea name="reason" required maxlength="1500"></textarea></label></div><div class="note">O código, o tipo e o saldo não são alterados aqui. Para corrigir saldo, use Movimentar.</div><div class="modal-actions">${btn('Cancelar','close','x')}<button type="submit" class="button primary">Salvar correção</button></div></form>`);}
function qrDialog(){openModal('Ler identificação','Aponte para a etiqueta ou informe o código manualmente.',`<div id="scannerArea"><button class="button primary full" data-action="startCamera">${icon('qr')}Ativar câmera</button><p class="scanner-hint" id="scannerHint">A leitura depende do suporte do navegador à câmera e ao leitor de QR Code.</p></div><form id="qrForm"><label><span class="field-label">Código ou conteúdo da etiqueta</span><input name="code" id="qrInput" placeholder="Ex.: DOR-MAD-001" required maxlength="2048" autocomplete="off"></label><div class="modal-actions"><button type="submit" class="button primary">${icon('search')}Localizar identificação</button></div></form>`);}
function stopScanner(){if(scannerFrame)cancelAnimationFrame(scannerFrame);scannerFrame=null;scannerStream?.getTracks().forEach(t=>t.stop());scannerStream=null;}
async function startCamera(){
  try{
    if(!window.isSecureContext)throw new Error('A câmera exige HTTPS ou localhost. Digite o código para continuar.');
    if(!('BarcodeDetector'in window)||!(await BarcodeDetector.getSupportedFormats()).includes('qr_code'))throw new Error('Este navegador não oferece leitura de QR Code. Use a identificação impressa na etiqueta.');
    if(!navigator.mediaDevices?.getUserMedia)throw new Error('Câmera indisponível. Digite a identificação.');
    $('scannerHint').textContent='Solicitando acesso à câmera…';
    const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});
    if(!$('modal').open||!$('scannerArea')){stream.getTracks().forEach(t=>t.stop());return;}scannerStream=stream;
    $('scannerArea').innerHTML='<div class="scanner-frame"><video id="scannerVideo" playsinline muted autoplay aria-label="Câmera para leitura de QR Code"></video></div><p class="scanner-hint">Aproxime a etiqueta. A câmera fecha ao concluir a leitura.</p>';
    const video=$('scannerVideo');video.srcObject=stream;await video.play();const detector=new BarcodeDetector({formats:['qr_code']});let last=0;
    const scan=async t=>{if(!scannerStream||!$('modal').open)return;if(t-last>200){last=t;try{const codes=await detector.detect(video);if(codes.length){resolveQR(codes[0].rawValue);return;}}catch(e){showError(new Error('A leitura falhou. Digite o código.'));stopScanner();return;}}scannerFrame=requestAnimationFrame(scan);};scannerFrame=requestAnimationFrame(scan);
  }catch(e){showError(new Error(e.name==='NotAllowedError'?'Permissão de câmera não concedida. Digite o código para continuar.':e.message));stopScanner();}
}
function resolveQR(raw){try{const code=D.parseQR(raw),i=state.items.find(x=>D.fold(x.code)===D.fold(code)||x.id===code);closeModal();if(i){navigate(navHref('registros',i.id));toast('Identificação encontrada. Confira os dados antes de salvar.');}else{ui.prefill=code;navigate('#registros');render();toast('Código ainda não cadastrado. Complete a identificação.');}}catch(e){showError(e);stopScanner();}}
function pendingDialog(){openModal('Situação dos dados',demo?'Dados fictícios de demonstração.':'As alterações estão salvas somente neste dispositivo.',`<div class="note warning">${navigator.onLine?'Há conexão com a internet, mas':'Sem conexão. Além disso,'} a integração com o servidor ainda não foi configurada. Nenhum item desta fila foi enviado.</div><h3>${fmt(state.outbox.length)} alterações locais</h3>${state.outbox.length?`<div class="audit-list">${state.outbox.slice(-50).reverse().map(e=>`<div><b>${esc(e.action)}</b><small>${dateTime(e.createdAt)} · Aguardando integração</small></div>`).join('')}</div><p class="small-copy">Exibindo as últimas ${Math.min(50,state.outbox.length)}. O backup inclui todos os registros.</p>`:'<p class="small-copy" style="margin-top:12px">Nenhuma alteração na fila.</p>'}<div class="modal-actions">${btn('Exportar backup completo','backup','download',true)}</div>`);}
function backup(){download(`maripora-backup-${D.today()}${demo?'-exemplo':''}.json`,JSON.stringify(state,null,2),'application/json');toast('Backup gerado. Guarde o arquivo em um local seguro.');}
function importDialog(){openModal('Importar backup','Restaure um arquivo Mariporã neste dispositivo.',`<div class="note">A importação substitui os dados desta versão local após sua confirmação. Antes, será exportada uma cópia dos dados atuais.</div><label class="file-drop"><span class="field-label">Arquivo JSON do backup</span><input type="file" id="backupFile" accept=".json,application/json"></label><div id="importReview"></div>`);}
async function prepareImport(file){if(!file)return;try{if(file.size>8*1024*1024)throw new Error('O backup excede 8 MB. Importe pelo processo de migração do backend.');let obj=JSON.parse(await file.text());if(Array.isArray(obj))obj=D.migrateLegacy(obj);else if(obj.materiais)obj=D.migrateLegacy(obj.materiais,obj.historico||[],obj.usuario||undefined);importCandidate=D.validateState(obj);$('importReview').innerHTML=`<div class="note"><strong>${fmt(obj.items.length)} identificações, ${fmt(obj.inspections.length)} inspeções e ${fmt(obj.history.length)} atividades.</strong><br>O arquivo substituirá a base local ativa${demo?' de demonstração':''}.</div>${btn('Confirmar restauração','confirmImport','upload',true)}`;}catch(e){importCandidate=null;showError(e);}}
function changeDemo(on){try{if(on&&!localStorage.getItem(D.DEMO_KEY))localStorage.setItem(D.DEMO_KEY,JSON.stringify(D.seedDemo()));key=on?D.DEMO_KEY:D.KEY;state=D.load(localStorage,key);demo=on;sessionStorage.setItem('maripora-demo',on?'1':'0');storageError='';ui.dirty=false;closeModal();navigate('#inicio');render();toast(on?'Ambiente de exemplo aberto. Seus dados continuam separados.':'Seus dados locais foram restaurados.');}catch(e){toast(e.message);}}
function generateReport(kind){try{const data=D.reportData(state,ui.reports);if(!data.items.length)throw new Error('Não há registros correspondentes aos filtros.');if(kind==='csv'){exportCSV(data);toast('Inventário exportado em CSV.');return;}if(kind==='xlsx')exportXLSX(data);else exportPDF(data,ui.reports.charts);try{commit(s=>{const ids=new Set(data.inspections.map(e=>e.id));for(const e of s.inspections)if(ids.has(e.id))e.reportedAt=D.iso();D.log(s,'Relatório',null,`${kind==='xlsx'?'Planilha Excel':'PDF'} gerado: ${data.items.length} identificações e ${data.inspections.length} inspeções.`,{format:kind,inspectionIds:[...ids],filters:D.clone(ui.reports)});},'Arquivo gerado com os filtros selecionados.');render();}catch(e){toast('Arquivo gerado, mas não foi possível atualizar as pendências: '+e.message);}}catch(e){toast(e.message);}}

document.addEventListener('submit',event=>{
  const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();if(!form.reportValidity())return;const fd=new FormData(form),data=Object.fromEntries(fd);
  try{
    if(form.id==='recordForm'){
      let savedId=form.dataset.item;const inspectData={date:data.inspectionDate,quantity:data.inspectionQuantity,condition:data.condition,defects:fd.getAll('defects'),notes:data.inspectionNotes};
      commit(s=>{const i=savedId?s.items.find(i=>i.id===savedId):D.addItem(s,data);if(!i)throw new Error('Identificação não encontrada.');savedId=i.id;if(form.dataset.item||data.includeInspection==='on')D.inspect(s,i.id,inspectData);},form.dataset.item?'Inspeção salva no histórico.':'Registro salvo com sucesso.');ui.prefill='';navigate(navHref('ficha',savedId));
    }else if(form.id==='countForm'){commit(s=>D.countItem(s,form.dataset.item,data.quantity,data.note),'Contagem salva.');closeModal();render();}
    else if(form.id==='movementForm'){commit(s=>D.move(s,form.dataset.item,data),'Movimentação salva. Saldo atualizado.');closeModal();render();}
    else if(form.id==='editForm'){commit(s=>D.correctItem(s,form.dataset.item,data,data.reason),'Correção registrada no histórico.');closeModal();render();}
    else if(form.id==='profileForm'){commit(s=>{if(data.profileName.trim().length<2)throw new Error('Informe o nome do responsável.');s.profile={name:data.profileName.trim(),email:data.email.trim(),role:data.role};},'Identificação local atualizada.');render();}
    else if(form.id==='qrForm')resolveQR(data.code);
  }catch(e){showError(e);}
});
document.addEventListener('input',event=>{const t=event.target;if(t.closest('#recordForm'))ui.dirty=true;if(t.dataset.filter&&t.tagName==='INPUT'&&t.type!=='date'){const group=ui[t.dataset.filter];group[t.dataset.key]=t.value;group.page=1;render(true);}});
document.addEventListener('change',event=>{
  const t=event.target;if(t.dataset.filter){const group=ui[t.dataset.filter];group[t.dataset.key]=t.value;group.page=1;render(true);}
  if(t.dataset.chart){ui.reports.charts=t.checked?[...new Set([...ui.reports.charts,t.dataset.chart])]:ui.reports.charts.filter(c=>c!==t.dataset.chart);render(true);}
  if(t.id==='includeInspection'){$('inspectionFields').disabled=!t.checked;$('inspectionFields').hidden=!t.checked;}
  if(t.id==='field-type'&&$('recordForm')){const wood=t.value==='Madeira';$('field-species').required=wood;$('field-species').disabled=!wood;if(!wood)$('field-species').value='Não se aplica';else if($('field-species').value==='Não se aplica')$('field-species').value='';}
  if(t.name==='scope'&&$('field-stock')){const unit=t.value==='unit';$('field-stock').readOnly=unit;if(unit)$('field-stock').value=1;$('field-inspectionQuantity').max=unit?'1':'';}
  if(t.id==='field-kind'&&$('movementForm')){$('field-quantity').min=t.value==='adjustment'?'0':'1';$('movementHelp').textContent=t.value==='adjustment'?'No ajuste, Quantidade é o novo saldo final, e não a diferença. Informe a justificativa.':'Entradas e saídas alteram o saldo. Após movimentar, será necessária uma nova conferência.';}
  if(t.id==='backupFile')prepareImport(t.files[0]);
});
document.addEventListener('click',async event=>{
  const navigation=event.target.closest('a[href^="#"]');
  if(navigation&&ui.dirty&&navigation.getAttribute('href')!==location.hash){if(!window.confirm('Sair deste formulário e descartar os dados ainda não salvos?')){event.preventDefault();return;}ui.dirty=false;}
  const preset=event.target.closest('[data-preset]');if(preset){ui.inventory.status=preset.dataset.preset;ui.inventory.page=1;if(location.hash==='#inventario')render();}
  const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
  try{
    if(action==='close')closeModal();else if(action==='qr')qrDialog();else if(action==='startCamera')await startCamera();else if(action==='count')countDialog(id);else if(action==='move')movementDialog(id);else if(action==='edit')editDialog(id);
    else if(action==='page'){ui[el.dataset.list].page=Number(el.dataset.page);render();$('page').focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});}
    else if(action==='clearFilters'){const f=route().name==='conferencia'?ui.conference:ui.inventory;for(const k of Object.keys(f))f[k]=k==='page'?1:'';render();}
    else if(action==='theme'){commit(s=>{s.preferences.theme=s.preferences.theme==='dark'?'light':'dark';});updateShell();if(route().name==='conta')render();}
    else if(action==='largeText'){commit(s=>{s.preferences.largeText=!s.preferences.largeText;});render();}
    else if(action==='pending')pendingDialog();else if(action==='backup')backup();else if(action==='import')importDialog();
    else if(action==='confirmImport'&&importCandidate){backup();const replacement=D.clone(importCandidate);replacement.revision=state.revision;D.log(replacement,'Restauração',null,'Backup importado após cópia de segurança da base anterior.');state=D.persist(localStorage,key,state,replacement);importCandidate=null;closeModal();render();toast('Backup restaurado.');}
    else if(action==='rawBackup'){const raw={};for(const k of [D.KEY,...Object.values(D.LEGACY)])raw[k]=localStorage.getItem(k);download('maripora-recuperacao-original.json',JSON.stringify(raw,null,2),'application/json');}
    else if(action==='demo')changeDemo(true);else if(action==='exitDemo')changeDemo(false);else if(['csv','xlsx','pdf'].includes(action))generateReport(action);
    else if(action==='copyCode'){const i=itemById(id);try{await navigator.clipboard.writeText(i.code);toast('Código copiado.');}catch{openModal('Código da identificação','Selecione e copie o código abaixo.',`<input value="${esc(i.code)}" readonly aria-label="Código da identificação">`);}}
    else if(action==='menu')openModal('Outras áreas','Continue o acompanhamento.',`<nav class="menu-list" aria-label="Todas as áreas">${NAV.filter(n=>n[0]!=='dashboard'||isAdmin()).map(([r,l,ico])=>`<a href="#${r}" data-action="close">${icon(ico)}${l}</a>`).join('')}<a href="#conta" data-action="close">${icon('user')}Conta e dados</a></nav>`);
    else if(action==='overview'){openModal('Indicadores da visão geral','Escolha os resumos que aparecem no início.',`${[['stock','Estoque atual'],['inspections','Inspeções pendentes'],['issues','Condições que precisam de atenção'],['counts','Conferidos hoje']].map(([v,l])=>`<label class="inline-check"><input type="checkbox" name="overviewCard" value="${v}" ${state.preferences.overview.includes(v)?'checked':''}>${l}</label>`).join('')}<div class="modal-actions">${btn('Salvar preferências','saveOverview','check',true)}</div>`);}
    else if(action==='saveOverview'){if(!isAdmin())throw new Error('Disponível apenas ao administrador.');const cards=[...document.querySelectorAll('[name=overviewCard]:checked')].map(e=>e.value);if(!cards.length)throw new Error('Mantenha pelo menos um indicador.');commit(s=>{s.preferences.overview=cards;});closeModal();render();}
    else if(action==='manual'){manualPDF(GUIDES);toast('Manual em PDF gerado.');}
    else if(action==='speak'){if(!('speechSynthesis'in window))throw new Error('Leitura em voz alta indisponível. Use o leitor de tela do dispositivo.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(GUIDES.map(g=>g[1]+'. '+g[3].join('. ')).join('. '));u.lang='pt-BR';u.rate=.95;speechSynthesis.speak(u);toast('Leitura iniciada. Use Parar leitura para encerrar.');}
    else if(action==='stopSpeak')window.speechSynthesis?.cancel();
    else if(action==='install'){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('installButton').hidden=true;}else openModal('Instalar Mariporã','Use o menu do navegador.',`<p class="small-copy">No Android, procure <b>Instalar app</b> ou <b>Adicionar à tela inicial</b> no menu. No iPhone, abra pelo Safari, toque em Compartilhar e em <b>Adicionar à Tela de Início</b>. A instalação exige HTTPS e varia conforme o navegador.</p>`);}
  }catch(e){showError(e);}
});
$('modal').addEventListener('close',()=>{stopScanner();modalReturnFocus?.focus?.({preventScroll:true});});
window.addEventListener('hashchange',()=>{ui.dirty=false;closeModal();render();$('page').focus({preventScroll:true});window.scrollTo(0,0);window.speechSynthesis?.cancel();});
window.addEventListener('beforeunload',e=>{if(ui.dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',updateShell);window.addEventListener('offline',updateShell);
window.addEventListener('storage',e=>{if(e.key===key)toast('Os dados foram alterados em outra aba. Recarregue antes de salvar.');});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('installButton').hidden=false;});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopScanner();});
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').catch(()=>{toast('O modo offline não está disponível nesta abertura. Os dados locais continuam salvos.');});
render();hydrateIcons();
